from pathlib import Path

process_memory = []
for status_path in Path('/proc').glob('[0-9]*/status'):
    pid = status_path.parent.name
    try:
        status = status_path.read_text()
        fields = dict(
            line.split(':', 1) for line in status.splitlines() if ':' in line
        )
        rss_kib = int(fields['VmRSS'].split()[0])
        pss_path = status_path.parent / 'smaps_rollup'
        pss_kib = None
        if pss_path.exists():
            for line in pss_path.read_text().splitlines():
                if line.startswith('Pss:'):
                    pss_kib = int(line.split()[1])
                    break
        cmdline = (status_path.parent / 'cmdline').read_bytes().replace(b'\0', b' ').decode(errors='replace').strip()
        name = fields['Name'].strip()
        process_memory.append((pss_kib or 0, rss_kib, int(pid), name, cmdline))
    except (FileNotFoundError, KeyError, PermissionError, ProcessLookupError, ValueError):
        pass

for pss_kib, rss_kib, pid, name, cmdline in sorted(process_memory, reverse=True)[:20]:
    print(f'{pid:>6}  PSS {pss_kib / 1024:>7.1f} MiB  RSS {rss_kib / 1024:>7.1f} MiB  {name:<18} {cmdline[:130]}')

