for status_path in Path('/proc').glob('[0-9]*/status'):
    proc = status_path.parent
    try:
        fields = dict(line.split(':', 1) for line in status_path.read_text().splitlines() if ':' in line)
        rss_kib = int(fields['VmRSS'].split()[0])
        pss_kib = 0
        for line in (proc / 'smaps_rollup').read_text().splitlines():
            if line.startswith('Pss:'):
                pss_kib = int(line.split()[1])
                break
        cmdline = (proc / 'cmdline').read_bytes().replace(b'\0', b' ').decode(errors='replace').strip()
        exe = (proc / 'exe').resolve().as_posix()
        memory_snapshot.append({
            'pid': int(proc.name), 'name': fields['Name'].strip(), 'pss': pss_kib,
            'rss': rss_kib, 'cmd': cmdline, 'exe': exe,
        })
    except (FileNotFoundError, KeyError, PermissionError, ProcessLookupError, ValueError):
        pass

by_exe = defaultdict(lambda: {'pss': 0, 'rss': 0, 'count': 0, 'names': set()})
for proc in memory_snapshot:
    group = by_exe[proc['exe']]
    group['pss'] += proc['pss']
    group['rss'] += proc['rss']
    group['count'] += 1
    group['names'].add(proc['name'])

total_pss_kib = sum(proc['pss'] for proc in memory_snapshot)
print(f'Process PSS total: {total_pss_kib / 1024:.1f} MiB across {len(memory_snapshot)} processes')
print('Top executable groups by PSS:')
for exe, group in sorted(by_exe.items(), key=lambda item: item[1]['pss'], reverse=True)[:35]:
    print(f"{group['pss'] / 1024:7.1f} MiB PSS  {group['rss'] / 1024:7.1f} MiB summed RSS  {group['count']:2} procs  {exe}")","title":"Attributing process memory","timeout":30,"reset":false}

