full_snapshot = []
for status_path in Path('/proc').glob('[0-9]*/status'):
    proc_path = status_path.parent
    try:
        fields = dict(line.split(':', 1) for line in status_path.read_text().splitlines() if ':' in line)
        rollup = {}
        for line in (proc_path / 'smaps_rollup').read_text().splitlines():
            if ':' in line:
                key, value = line.split(':', 1)
                parts = value.split()
                if parts and parts[0].isdigit():
                    rollup[key] = int(parts[0])
        cmdline = (proc_path / 'cmdline').read_bytes().replace(b'\0', b' ').decode(errors='replace').strip()
        full_snapshot.append({
            'pid': int(proc_path.name),
            'name': fields['Name'].strip(),
            'cmd': cmdline,
            'exe': proc_path.joinpath('exe').resolve().as_posix(),
            'pss': rollup.get('Pss', 0),
            'anon': rollup.get('Pss_Anon', 0),
            'file': rollup.get('Pss_File', 0),
            'shmem': rollup.get('Pss_Shmem', 0),
            'uss': rollup.get('Private_Clean', 0) + rollup.get('Private_Dirty', 0),
        })
    except (FileNotFoundError, KeyError, PermissionError, ProcessLookupError, ValueError):
        pass

category_totals = defaultdict(lambda: {'pss': 0, 'uss': 0, 'count': 0})
for proc in full_snapshot:
    if '/.tarball-installations/zen/zen' in proc['exe']:
        category = 'Zen browser'
    elif ('/.local/bin/omp' in proc['exe'] or '/tmp/omp-python-runner/' in proc['cmd']):
        category = 'OpenCode/OMP'
    elif (proc['pid'] in {95691, 95692, 95853, 97932, 95688} or proc['cmd'].startswith('uv run marimo')):
        category = 'Marimo notebook'
    elif proc['exe'] == '/usr/bin/ghostty':
        category = 'Ghostty terminal'
    elif proc['exe'] == '/usr/bin/Hyprland':
        category = 'Hyprland compositor'
    else:
        category = 'Other processes'
    category_totals[category]['pss'] += proc['pss']
    category_totals[category]['uss'] += proc['uss']
    category_totals[category]['count'] += 1

print(f"Processes scanned: {len(full_snapshot)}")
print(f"Total process PSS: {sum(p['pss'] for p in full_snapshot)/1024:.1f} MiB")
print(f"PSS anon/file/shmem: {sum(p['anon'] for p in full_snapshot)/1024:.1f} / {sum(p['file'] for p in full_snapshot)/1024:.1f} / {sum(p['shmem'] for p in full_snapshot)/1024:.1f} MiB")
print('\nPrimary attribution:')
for name, metrics in sorted(category_totals.items(), key=lambda item: item[1]['pss'], reverse=True):
    print(f"{name:<20} {metrics['pss']/1024:7.1f} MiB PSS  {metrics['uss']/1024:7.1f} MiB unique  {metrics['count']:2} processes")
print('\nOther executable groups at or above 10 MiB PSS:')
other_groups = defaultdict(lambda: [0, 0])
for proc in full_snapshot:
    if proc['exe'] not in {'/home/rev/.tarball-installations/zen/zen', '/home/rev/.local/bin/omp', '/usr/bin/ghostty', '/usr/bin/Hyprland', '/home/rev/.local/share/uv/python/cpython-3.12.12-linux-x86_64-gnu/bin/python3.12', '/home/rev/.local/bin/uv'}:
        other_groups[proc['exe']][0] += proc['pss']
        other_groups[proc['exe']][1] += 1
for exe, (pss, count) in sorted(other_groups.items(), key=lambda item: item[1][0], reverse=True):
    if pss >= 10 * 1024:
        print(f"{pss/1024:7.1f} MiB  {count:2}  {exe}")

