import html as _html
import json as _json
from pathlib import Path as _Path

result = pipeline_result
stats = result['stage_stats']
manifest = result['manifest']


def esc(value):
    return _html.escape(str(value), quote=True)


def fmt(value):
    return f'{int(value):,}'


def pct(value):
    return f'{value:.2f}%'


def table(headers, rows):
    head = ''.join(f'<th>{esc(header)}</th>' for header in headers)
    body = ''.join(
        '<tr>' + ''.join(f'<td>{esc(row.get(header, ""))}</td>' for header in headers) + '</tr>'
        for row in rows
    )
    return f'<div class="table-wrap"><table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>'

stage_rows = []
stage_json = []
for index, stage in enumerate(stats):
    previous = stats[index - 1] if index else stage
    removed = max(0, previous['documents'] - stage['documents'])
    retained = 100 * stage['documents'] / max(previous['documents'], 1)
    row = {
        'Stage': stage['stage'],
        'Documents after': fmt(stage['documents']),
        'Documents removed': fmt(removed),
        'Characters after': fmt(stage['characters']),
        'Estimated tokens after': fmt(stage['estimated_tokens']),
        'Retained from previous': pct(retained),
    }
    stage_rows.append(row)
    stage_json.append({
        'stage': stage['stage'],
        'documents': stage['documents'],
        'characters': stage['characters'],
        'tokens': stage['estimated_tokens'],
        'removed': removed,
    })

strategy_rows = [
    {'#': 1, 'Strategy': 'Extract', 'Decision': 'Remove HTML tags, scripts, layout lines, and explicit cookie/navigation boilerplate.'},
    {'#': 2, 'Strategy': 'Normalize', 'Decision': 'Decode entities, repair common mojibake, NFC-normalize, normalize whitespace and markers; preserve Indic ZWJ/ZWNJ.'},
    {'#': 3, 'Strategy': 'Language ID and validation', 'Decision': 'Validate Hindi Devanagari, Hindi Latin, and code-mixed text instead of trusting the split label.'},
    {'#': 4, 'Strategy': 'Quality filtering', 'Decision': 'Use length, malformed-symbol, link-density, repetition, and vocabulary-diversity heuristics.'},
    {'#': 5, 'Strategy': 'Deduplication', 'Decision': 'Use exact SHA-256 plus local MinHash/LSH near-duplicate detection.'},
    {'#': 6, 'Strategy': 'PII scrubbing', 'Decision': 'Redact emails, Indian phones, IPv4, credentials, and Aadhaar-like identifiers; show counts only.'},
    {'#': 7, 'Strategy': 'Decontamination', 'Decision': 'Run a limited textual proxy for named benchmark and evaluation markers and disclose its scope.'},
    {'#': 8, 'Strategy': 'Manifest / provenance', 'Decision': 'Record source, license, revision, sample rule, hashes, version, timestamp, and methods.'},
]
removal_rows = [
    {'Reason': 'Language mismatch', 'Documents': fmt(result['language_removed'])},
]
removal_rows += [
    {'Reason': f'Quality: {reason}', 'Documents': fmt(count)}
    for reason, count in sorted(result['quality_reasons'].items())
]
removal_rows += [
    {'Reason': 'Exact duplicate', 'Documents': fmt(result['duplicate_counts']['exact_removed'])},
    {'Reason': 'Near duplicate', 'Documents': fmt(result['duplicate_counts']['near_removed'])},
    {'Reason': 'Decontamination proxy', 'Documents': fmt(result['decontamination_documents'])},
]
language_before_rows = [
    {'Detected language': language, 'Documents': fmt(count)}
    for language, count in result['language_before'].items()
]
language_after_rows = [
    {'Detected language': language, 'Documents': fmt(count)}
    for language, count in result['language_after'].items()
]
pii_rows = [
    {'PII category': category, 'Matches redacted': fmt(count)}
    for category, count in sorted(result['pii_counts'].items())
] or [{'PII category': 'None detected', 'Matches redacted': '0'}]
manifest_rows = [{'Field': key, 'Value': value} for key, value in manifest.items()]
raw_docs = stats[0]['documents']
final_stage = stats[-1]
final_docs = final_stage['documents']
retention = 100 * final_docs / max(raw_docs, 1)

html = f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Hindi Data Cleaning Case Study · Session 4</title>
<style>
:root {{ color-scheme: dark; --bg:#0b1020; --panel:#121a2d; --panel2:#18233a; --ink:#edf3ff; --muted:#9db0cf; --accent:#78e2c0; --accent2:#7fb2ff; --line:#2d3b59; --warn:#ffd27d; }}
* {{ box-sizing:border-box; }} body {{ margin:0; font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif; background:radial-gradient(circle at 10% 0%,#1c3154 0,#0b1020 40rem); color:var(--ink); line-height:1.55; }}
main {{ max-width:1180px; margin:0 auto; padding:42px 20px 80px; }} header {{ display:flex; gap:24px; justify-content:space-between; align-items:flex-start; margin-bottom:30px; }} h1 {{ font-size:clamp(2rem,5vw,4rem); line-height:1.05; margin:8px 0 14px; letter-spacing:-.04em; }} h2 {{ margin-top:0; font-size:1.45rem; }} h3 {{ color:var(--accent); margin-bottom:8px; }} p {{ color:var(--muted); }} a {{ color:var(--accent2); }} .eyebrow {{ color:var(--accent); text-transform:uppercase; letter-spacing:.16em; font-weight:700; font-size:.75rem; }} .badge {{ background:var(--accent); color:#071b17; padding:10px 14px; border-radius:999px; font-weight:800; white-space:nowrap; }} .panel {{ background:color-mix(in srgb,var(--panel) 92%,transparent); border:1px solid var(--line); border-radius:18px; padding:24px; margin:18px 0; box-shadow:0 18px 50px #0003; }} .grid {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; }} .metric {{ background:var(--panel2); border:1px solid var(--line); border-radius:14px; padding:16px; }} .metric strong {{ display:block; font-size:1.6rem; color:var(--ink); }} .metric span {{ color:var(--muted); font-size:.85rem; }} .table-wrap {{ overflow:auto; border:1px solid var(--line); border-radius:12px; margin:12px 0 18px; }} table {{ width:100%; border-collapse:collapse; min-width:640px; }} th,td {{ padding:11px 13px; border-bottom:1px solid var(--line); text-align:left; vertical-align:top; }} th {{ background:#1b2943; color:var(--accent); position:sticky; top:0; }} tr:last-child td {{ border-bottom:0; }} details {{ border-top:1px solid var(--line); padding:15px 0; }} details:first-of-type {{ border-top:0; }} summary {{ cursor:pointer; font-weight:750; }} .controls {{ display:flex; flex-wrap:wrap; gap:12px; align-items:center; background:#0c1528; padding:14px; border-radius:12px; }} select {{ background:var(--panel2); color:var(--ink); border:1px solid var(--line); border-radius:8px; padding:8px; }} .stage-card {{ margin-top:14px; }} .bar {{ height:12px; background:#263655; border-radius:99px; overflow:hidden; }} .bar i {{ display:block; height:100%; background:linear-gradient(90deg,var(--accent),var(--accent2)); border-radius:99px; transition:width .25s ease; }} .note {{ border-left:3px solid var(--warn); padding-left:14px; }} footer {{ color:var(--muted); border-top:1px solid var(--line); margin-top:30px; padding-top:20px; font-size:.9rem; }} code {{ color:var(--accent); }}
@media (max-width:680px) {{ header {{ display:block; }} .badge {{ display:inline-block; margin-top:10px; }} main {{ padding:26px 12px 60px; }} .panel {{ padding:17px; }} }}
</style>
</head>
<body>
<main>
<header><div><div class="eyebrow">ERA V5 · Session 4</div><h1>Hindi web text, cleaned with evidence.</h1><p>A small, hands-on case study applying the lecture's eight minimum cleaning strategies to a reproducible Sangraha sample.</p></div><div class="badge">8 strategies</div></header>
<section class="panel"><div class="grid"><div class="metric"><strong>{fmt(raw_docs)}</strong><span>raw documents</span></div><div class="metric"><strong>{fmt(final_docs)}</strong><span>final documents</span></div><div class="metric"><strong>{fmt(stats[0]['estimated_tokens'])}</strong><span>raw estimated tokens</span></div><div class="metric"><strong>{fmt(final_stage['estimated_tokens'])}</strong><span>final estimated tokens</span></div><div class="metric"><strong>{pct(retention)}</strong><span>document retention</span></div></div></section>
<section class="panel"><h2>1. How many strategies, and what are they?</h2>{table(['#','Strategy','Decision'], strategy_rows)}</section>
<section class="panel"><h2>2. What dataset was picked?</h2><p><a href="{esc(SOURCE_URL)}">{esc(DATASET_ID)}</a>, configuration <code>{esc(manifest['config'])}</code>, split <code>{esc(manifest['split'])}</code>, license <strong>{esc(manifest['license'])}</strong>. This is the Session 3 document-level Hindi web corpus, not the lecture's Qwen demo dataset.</p><p>Selection: deterministic first rows from the streaming split until the estimated-token target. Fertility assumption: <strong>{TOKEN_FERTILITY_ASSUMPTION} estimated tokens per non-whitespace unit</strong>. The raw sample is cached locally as JSONL before processing.</p></section>
<section class="panel"><h2>3. What was cleaned and why?</h2><div class="grid"><div><h3>Extract and normalize</h3><p>HTML tags, scripts, layout noise, cookie/navigation boilerplate, entities, mojibake, inconsistent whitespace, and chat-template markers are handled. NFC is used; semantic Indic joiners are preserved.</p></div><div><h3>Validate and filter</h3><p>Text is classified as Hindi Devanagari, Hindi Latin, mixed Hindi, or other. Quality rules remove short, malformed, link-heavy, repetitive, and low-diversity documents without requiring English punctuation.</p></div><div><h3>Deduplicate and scrub</h3><p>Exact SHA-256 and a local MinHash/LSH approximation remove repeated documents. PII is redacted in place; only category counts are shown here.</p></div></div></section>
<section class="panel"><h2>4. Additional strategy / concern</h2><p>Indic Unicode safety is the dataset-specific concern. ZWJ and ZWNJ are meaningful in Brahmic scripts and are preserved. Hindi Latin-script speech and natural Hinglish are retained when supported by the language heuristic. Ghost tags are treated as normalization, not as a ninth canonical stage.</p></section>
<section class="panel"><h2>5. Final statistics</h2><div class="controls"><label for="stage-select">Inspect one stage:</label><select id="stage-select"></select><span id="stage-summary"></span></div><div class="stage-card"><div class="bar"><i id="stage-bar" style="width:0%"></i></div></div>{table(['Stage','Documents after','Documents removed','Characters after','Estimated tokens after','Retained from previous'], stage_rows)}</section>
<section class="panel"><details open><summary>Removal counts by reason</summary>{table(['Reason','Documents'], removal_rows)}</details><details><summary>Detected language mix before validation</summary>{table(['Detected language','Documents'], language_before_rows)}</details><details><summary>Detected language mix after final filtering</summary>{table(['Detected language','Documents'], language_after_rows)}</details><details><summary>PII category counts (removed values are never exposed)</summary>{table(['PII category','Matches redacted'], pii_rows)}</details><details><summary>Exact versus near duplicates</summary><p>Exact removed: <strong>{fmt(result['duplicate_counts']['exact_removed'])}</strong>. Near removed: <strong>{fmt(result['duplicate_counts']['near_removed'])}</strong>.</p><p>{esc(result['duplicate_counts']['method'])}</p></details><details><summary>Decontamination result and limitation</summary><p>Removed <strong>{fmt(result['decontamination_documents'])}</strong> documents using a limited textual proxy over GSM8K, MMLU, HellaSwag, Winogrande, TruthfulQA, BIG-bench, ARC Challenge, benchmark-answer, and eval-harness markers. No full benchmark corpus was downloaded, so this is not a complete contamination guarantee.</p></details></section>
<section class="panel"><details><summary>Manifest / provenance</summary>{table(['Field','Value'], manifest_rows)}</details></section>
<footer>Pipeline version <code>{esc(manifest['pipeline_version'])}</code> · Run UTC <code>{esc(manifest['run_utc'])}</code> · Raw and final SHA-256 hashes are recorded in the manifest. No document text or PII values are published.</footer>
</main>
<script>
const stages = {_json.dumps(stage_json, ensure_ascii=False)};
const select = document.getElementById('stage-select');
const summary = document.getElementById('stage-summary');
const bar = document.getElementById('stage-bar');
stages.forEach((stage, index) => {{ const option = document.createElement('option'); option.value = index; option.textContent = stage.stage; select.appendChild(option); }});
function renderStage() {{ const stage = stages[Number(select.value)]; const base = stages[0].documents || 1; summary.textContent = `${{stage.documents.toLocaleString()}} documents · ${{stage.tokens.toLocaleString()}} estimated tokens · ${{stage.removed.toLocaleString()}} removed at this stage`; bar.style.width = `${{Math.max(2, 100 * stage.documents / base)}}%`; }}
select.addEventListener('change', renderStage); renderStage();
</script>
</body></html>
'''

site = _Path('site')
site.mkdir(parents=True, exist_ok=True)
(site / 'index.html').write_text(html, encoding='utf-8')
print({'path': str(site / 'index.html'), 'bytes': len(html.encode('utf-8')), 'stages': len(stage_rows), 'final_documents': final_docs})

