import marimo._code_mode as cm
from pathlib import Path

namespace = {}
exec(Path('/tmp/extraction_experiment_cells.py').read_text(encoding='utf-8'), namespace)
cell_sources = {
    'extraction_scope': namespace['scope_code'],
    'extraction_technique_map': namespace['methods_code'],
    'extraction_setup': namespace['setup_code'],
    'extraction_controls': namespace['controls_code'],
    'extraction_run': namespace['run_code'],
    'extraction_evidence': namespace['evidence_code'],
}

async with cm.get_context() as ctx:
    by_name = {cell.name: cell for cell in ctx.cells if cell.name}
    for name, source in cell_sources.items():
        if name in by_name:
            cell_id = by_name[name].id
            ctx.edit_cell(cell_id, code=source)
        else:
            cell_id = ctx.create_cell(source, name=name, hide_code=True)
        ctx.run_cell(cell_id)
        print(f'{name}: {cell_id}')

